subsection.code_block:
#include <cstdint>
#include <cstring>
#include <string>
#include <vector>

#pragma pack(push, 1)
struct studiohdr_t {
    char id[4];             // FourCC "IDST"
    int32_t version;        // Versión 10 en GoldSrc
    char name[64];          // Nombre interno del modelo
    int32_t length;         // Tamaño del archivo binario
    float eyeposition[3];    
    float min[3];            
    float max[3];            
    float bbmin[3];          
    float bbmax[3];          
    int32_t flags;          
    int32_t numbones;             // 140
    int32_t boneindex;            // 144
    int32_t numbonecontrollers;   // 148  <-- omitido en la primera version de esta guia
    int32_t bonecontrollerindex;  // 152  <--
    int32_t numhitboxes;          // 156  <--
    int32_t hitboxindex;          // 160  <--
    int32_t numseq;               // 164  numero de secuencias de animacion
    int32_t seqindex;             // 168  offset al arreglo mstudioseqdesc_t
    int32_t numseqgroups;         // 172  1 = todo aqui, >1 = hay archivos laterales
    int32_t seqgroupindex;        // 176
    int32_t numtextures;          // 180  0 = las texturas estan en <nombre>T.mdl
    int32_t textureindex;         // 184
    // ... el header sigue; la lista completa esta en mdl10_structs.h
};

// 176 bytes. Los campos que un parser no use igual van escritos: una estructura con agujeros
// es una estructura cuyos campos posteriores estan todos corridos.
struct mstudioseqdesc_t {
    char label[32];               // 0    nombre de la secuencia, "reload"
    float fps;                    // 32
    int32_t flags;                // 36   bit 0 = STUDIO_LOOPING
    int32_t activity;             // 40
    int32_t actweight;            // 44
    int32_t numevents;            // 48
    int32_t eventindex;           // 52   offset ABSOLUTO en el archivo
    int32_t numframes;            // 56
    int32_t numpivots;            // 60
    int32_t pivotindex;           // 64
    int32_t motiontype;           // 68
    int32_t motionbone;           // 72
    float linearmovement[3];      // 76
    int32_t automoveposindex;     // 88
    int32_t automoveangleindex;   // 92
    float bbmin[3];               // 96
    float bbmax[3];               // 108
    int32_t numblends;            // 120
    int32_t animindex;            // 124  offset ABSOLUTO, cuando seqgroup es 0
    int32_t blendtype[2];         // 128
    float blendstart[2];          // 136
    float blendend[2];            // 144
    int32_t blendparent;          // 152
    int32_t seqgroup;             // 156  0 = las pistas estan aqui, >0 = en <nombre>NN.mdl
    int32_t entrynode;            // 160
    int32_t exitnode;             // 164
    int32_t nodeflags;            // 168
    int32_t nextseq;              // 172
};

// 76 bytes. El de Source es OTRA estructura, de 80; ver la seccion de eventos.
struct mstudioevent_t {
    int32_t frame;          // 0   cuadro exacto de ejecucion
    int32_t event;          // 4   5004 = sonido de cliente
    int32_t type;           // 8   sin usar
    char options[64];       // 12  ruta relativa a sound/, sin terminador garantizado
};

// 104 bytes. Uno por archivo entre los que el modelo reparte sus animaciones.
struct mstudioseqgroup_t {
    char label[32];
    char name[64];          // la ruta que escribio el compilador, obsoleta si lo renombraron
    int32_t unused;
    int32_t unused2;
};
#pragma pack(pop)

struct ModelDependencyGraph {
    std::string model_path;
    std::vector<std::string> sound_dependencies;
    std::vector<std::string> texture_dependencies;
};

ModelDependencyGraph ParseGoldSrcDependencies(const uint8_t* buffer, size_t size) {
    ModelDependencyGraph graph;
    if (size < sizeof(studiohdr_t)) return graph;

    const auto* header = reinterpret_cast<const studiohdr_t*>(buffer);

    if (std::memcmp(header->id, "IDST", 4) != 0 || header->version != 10) {
        return graph;
    }

    // Todo offset viene de un archivo que puede estar truncado o mal formado. Se comprueba por
    // resta y division, nunca por suma: offset + n * sizeof desborda en silencio y la
    // comprobacion pasa justo cuando no deberia.
    auto fits = [size](int32_t offset, int32_t count, size_t stride) {
        if (offset < 0 || count < 0) return false;
        if (static_cast<size_t>(offset) > size) return false;
        if (count != 0 && stride > (size - static_cast<size_t>(offset))
                                       / static_cast<size_t>(count)) {
            return false;
        }
        return true;
    };

    if (header->numseq <= 0 || header->seqindex <= 0) return graph;
    if (!fits(header->seqindex, header->numseq, sizeof(mstudioseqdesc_t))) return graph;

    const auto* sequences = reinterpret_cast<const mstudioseqdesc_t*>(buffer + header->seqindex);

    for (int i = 0; i < header->numseq; ++i) {
        const auto& seq = sequences[i];
        if (seq.numevents <= 0 || seq.eventindex <= 0) continue;
        if (!fits(seq.eventindex, seq.numevents, sizeof(mstudioevent_t))) continue;

        const auto* events = reinterpret_cast<const mstudioevent_t*>(buffer + seq.eventindex);

        for (int j = 0; j < seq.numevents; ++j) {
            const auto& evt = events[j];

            // Los tres ids que significan "hace ruido". GoldSrc no tiene eventos con nombre,
            // asi que el numero es lo unico que distingue un disparo de un fogonazo o de un
            // casquillo cayendo.
            if (evt.event != 5004 && evt.event != 1004 && evt.event != 1008) continue;

            // options es char[64] y no garantiza terminador: acotar el escaneo a su tamano.
            const size_t len = ::strnlen(evt.options, sizeof(evt.options));
            if (len == 0) continue;

            std::string name(evt.options, len);
            // Un ! al frente marca una frase de sound/sentences.txt, que no es un archivo.
            if (name[0] == '!') continue;
            graph.sound_dependencies.push_back("sound/" + name);
        }
    }

    return graph;
}
